using System.Text.Json;

namespace Metarill.Generation;

/// <summary>C#只负责展开原YZP模板；页面、布局与操作合同沿用原前端。</summary>
internal static class UniappRenderer
{
    /// <summary>原列表和详情共享同一元数据快照，尚未交付的后端控件仍写入能力缺口。</summary>
    public static IEnumerable<PlannedFile> Render(GenerationModel model)
    {
        var routes=new List<object>();var gaps=GenerationCapabilityAudit.Collect(model);var children=ChildrenCompilation.Compile(model);
        foreach(var table in model.Tables)
        foreach(var page in table.Pages)
        {
            var stem=table.Source.TableName;var list=$"pages/yzp/{stem}-list-{page.Source.Id}";var detail=$"pages/yzp/{stem}-detail-{page.Source.Id}";
            yield return new("frontend/"+list+".vue",OriginalUniappListRenderer.Render(model,table,page));
            yield return new("frontend/"+detail+".vue",OriginalUniappDetailRenderer.Render(model,table,page,children.Where(child=>child.Parent==page).ToArray()));
            routes.Add(new{path=list,style=new{navigationBarTitleText=page.Source.Name,navigationStyle="custom",enablePullDownRefresh=true}});
            routes.Add(new{path=detail,style=new{navigationBarTitleText=page.Source.Name,navigationStyle="custom"}});
        }
        // 固定可信模块才附带原自定义工作台路由；普通业务目录不能自报标记获得入口。
        routes.AddRange(TrustedSecurityWorkbenchRenderer.Routes(model));
        var subsets=new List<object>();
        subsets.AddRange(model.Tables.SelectMany(table=>table.Pages.SelectMany(page=>MultiSelectCompilation.ForPage(model,table,page).Select(def=>DerivedMultiNamesCompilation.Declared(model,def.Target,def.Name)?(object)new{controlKind="MultiSelectPage",tableId=table.Source.Id,columnId=def.Source.Source.Id,pageId=page.Source.Id,targetPageId=def.TargetPage.Source.Id,storageMode="nonRedundant",extraScopeSupported=false,renamePropagationSupported=false,nonRedundantSupported=true,derivedNameSupported=true}:new{controlKind="MultiSelectPage",tableId=table.Source.Id,columnId=def.Source.Source.Id,pageId=page.Source.Id,targetPageId=def.TargetPage.Source.Id,storageMode=table.Source.IsRongyu==0?"nonRedundant":"redundant",extraScopeSupported=false,renamePropagationSupported=RelationPropagationCompilation.Supports(model,table,def.Source),nonRedundantSupported=table.Source.IsRongyu==0}))));
        subsets.AddRange(model.Tables.SelectMany(table=>table.Pages.SelectMany(page=>CascadeTreeReadCompilation.ForPage(model,table,page).Where(plan=>NonRedundantSelfTreeSubset.Supports(model,table,page,plan.Source)).Select(plan=>(object)new{controlKind="CascadeTree",sourceMode="selfTree",tableId=table.Source.Id,columnId=plan.Source.Source.Id,pageId=page.Source.Id,targetPageId=plan.TargetPage.Source.Id,storageMode="nonRedundant",nonRedundantSupported=true,sameTableSupported=plan.Target.Source.Id==table.Source.Id,sourceParentSupported=page.Scopes.Any(scope=>scope.Source=="parent"),mixedRelationsSupported=table.Columns.Any(column=>column.Source.ControlKind!="CascadeTree"&&Metarill.Core.Metadata.MetadataStoragePolicy.IsRelationColumn(column.Source)),multipleSelfTreesSupported=CascadeTreeWriteCompilation.ForService(model,table,page).Count>1,mixedCascadeModesSupported=CrossTableWriteCompilation.ForService(model,table,page).Count>0,derivedNameSupported=plan.DerivedName,renamePropagationSupported=false}))));
        subsets.AddRange(model.Tables.SelectMany(table=>table.Pages.SelectMany(page=>DatabaseCheckboxCompilation.ForPage(model,table,page).Select(def=>(object)new{controlKind="MultiCheckBoxDatabase",tableId=table.Source.Id,columnId=def.Source.Source.Id,pageId=page.Source.Id,targetTableId=def.Target.Source.Id,storageMode=table.Source.IsRongyu==0?"nonRedundant":"redundant",nameField="name",maximumItems=5000,sourceActionAny=true,derivedNameSupported=def.DerivedName,globalTargetSupported=false,renamePropagationSupported=RelationPropagationCompilation.Supports(model,table,def.Source)}))));
        subsets.AddRange(model.Tables.Where(table=>table.Source.IsRongyu==1).SelectMany(table=>table.Pages.SelectMany(page=>CrossTableWriteCompilation.ForService(model,table,page).Select(plan=>(object)new{controlKind="CascadeTree",sourceMode="crossTable",tableId=table.Source.Id,columnId=plan.Read.Source.Source.Id,pageId=page.Source.Id,storageMode="redundant",sameSourceTableSupported=plan.Read.Levels.Any(level=>level.Target.Source.Id==table.Source.Id),repeatedSourceRolesSupported=plan.Read.Levels.Count(level=>level.Target.Source.Id==table.Source.Id)>1,renamePropagationSupported=RelationPropagationCompilation.Bindings(model).Any(binding=>binding.Source.Source.Id==table.Source.Id&&binding.CrossTableColumnId==plan.Read.Source.Source.Id),fullApplicationAccepted=false}))));
        subsets.AddRange(model.Tables.SelectMany(table=>table.Pages.SelectMany(page=>CrossTableWriteCompilation.ForService(model,table,page).Where(plan=>NonRedundantCrossTableSubset.Supports(model,table,page,plan.Read.Source)).Select(plan=>(object)new{controlKind="CascadeTree",sourceMode="crossTable",tableId=table.Source.Id,columnId=plan.Read.Source.Source.Id,pageId=page.Source.Id,storageMode="nonRedundant",nonRedundantSupported=true,partialSelectionSupported=true,sameSourceTableSupported=plan.Read.Levels.Any(level=>level.Target.Source.Id==table.Source.Id),repeatedSourceRolesSupported=plan.Read.Levels.Count(level=>level.Target.Source.Id==table.Source.Id)>1,sourceParentSupported=page.Scopes.Any(scope=>scope.Source=="parent"),multipleCrossTablesSupported=CrossTableWriteCompilation.ForService(model,table,page).Count>1,mixedCascadeModesSupported=CascadeTreeWriteCompilation.ForService(model,table,page).Count>0,pathCellImportSupported=false,pathCellExportSupported=false,customPropertyAliasesSupported=false,derivedNameSupported=plan.Read.Levels.Any(level=>level.DerivedName),renamePropagationSupported=false}))));
        subsets.AddRange(model.Tables.SelectMany(table=>table.Pages.SelectMany(page=>RelationCompilation.ForPage(model,page).Where(relation=>DerivedRelationNamesCompilation.Declared(model,relation)).Select(relation=>(object)new{controlKind=relation.SourceColumn.Source.ControlKind,tableId=table.Source.Id,columnId=relation.SourceColumn.Source.Id,pageId=page.Source.Id,targetPageId=relation.TargetPage.Source.Id,storageMode="nonRedundant",derivedNameSupported=true,sqlNameFilterBeforePaging=true,sourceParentSupported=relation.SourceParents.Count>0,targetParentSupported=relation.TargetParents.Count>0,formScopeSupported=RelationConditionsCompilation.HasForms(relation),renamePropagationSupported=false}))));
        yield return new("generation-capabilities.json",JsonSerializer.Serialize(new{schemaVersion=1,unsupportedControls=gaps,supportedControlSubsets=subsets},Options)+"\n");
        yield return new("frontend/pages.generated.json",JsonSerializer.Serialize(new{pages=routes},Options)+"\n");
    }
    private static readonly JsonSerializerOptions Options=new(){WriteIndented=true,NewLine="\n"};
}
